import { readdirSync, readFileSync } from 'node:fs';
import { join, relative } from 'node:path';
import { describe, expect, it } from 'vitest';

/**
 * Guard for the IPC contract types: the Rust DTOs are generated by ts-rs into
 * `src/lib/contracts/generated/`, so no file elsewhere in `src/lib` may
 * declare its own `interface` or `type X =` under a generated name, nor under
 * one of the names the hand-written mirrors used to carry. Re-exports
 * (`export type { X } from '#lib/contracts/index.js'`) are fine.
 */

const ROOT = process.cwd();
const LIB = join(ROOT, 'src/lib');
const GENERATED = join(LIB, 'contracts/generated');

/** Names the old mirrors were declared under that are not `<Generated>V2`. */
const RENAMED_MIRRORS = ['TauriDebugLogPayload', 'SemanticSearchResult', 'SearchIndexStats'];

/**
 * TS-domain types that share a generated name but are not wire mirrors, as
 * `file -> name`.
 */
const ALLOWLIST: string[] = [];

/** Every `.ts` file name under the generated dir, without extension. */
function generatedNames(): string[] {
	return readdirSync(GENERATED, { recursive: true, encoding: 'utf8' })
		.filter((f) => f.endsWith('.ts'))
		.map((f) => f.replace(/^.*\//, '').replace(/\.ts$/, ''));
}

/** The forbidden declaration names: generated, `<generated>V2`, and renamed mirrors. */
function forbiddenNames(): Set<string> {
	const names = generatedNames();
	return new Set([...names, ...names.map((n) => `${n}V2`), ...RENAMED_MIRRORS]);
}

/** Source files under `src/lib`, outside `contracts/`. */
function libFiles(): string[] {
	return readdirSync(LIB, { recursive: true, encoding: 'utf8' })
		.filter((f) => /\.(ts|svelte)$/.test(f))
		.map((f) => join(LIB, f))
		.filter((f) => !f.startsWith(join(LIB, 'contracts') + '/'));
}

/**
 * An `interface X` or `type X =` declaration. A `type` alias needs its `=`:
 * a bare `type X` line is an inline type specifier in a multi-line import.
 */
const DECLARATION =
	/^\s*(?:export\s+)?(?:declare\s+)?(?:interface\s+([A-Za-z_$][\w$]*)\b|type\s+([A-Za-z_$][\w$]*)\s*(?:<[^=]*>)?\s*=)/gm;

/** The declared name of a `DECLARATION` match. */
function declaredName(m: RegExpMatchArray): string {
	return m[1] ?? m[2];
}

/** `file:line name` for each declaration in `source` whose name is forbidden and not in `allowlist`. */
function findMirrors(file: string, source: string, forbidden: Set<string>, allowlist: string[] = ALLOWLIST): string[] {
	const hits: string[] = [];
	for (const m of source.matchAll(DECLARATION)) {
		const name = declaredName(m);
		if (!forbidden.has(name)) continue;
		if (allowlist.includes(`${file} -> ${name}`)) continue;
		const line = source.slice(0, m.index).split('\n').length;
		hits.push(`${file}:${line} ${name}`);
	}
	return hits;
}

describe('IPC mirrors', () => {
	it('flags interface and type declarations under a generated or mirror name', () => {
		const forbidden = new Set(['NoteEntry', 'NoteEntryV2', 'SearchIndexStats']);
		const source = [
			"export type { NoteEntry as NoteEntryV2 } from '#lib/contracts/index.js';",
			"import type { NoteEntry } from '#lib/contracts/index.js';",
			'export interface NoteEntryV2 {',
			'}',
			'\ttype SearchIndexStats = { added?: number };',
			'interface NoteEntry { path: string }',
			'export interface NoteEntryView {}',
			'import {',
			'\ttype NoteEntry,',
			"} from './x';",
			'export type NoteEntry<T> = T;',
		].join('\n');
		expect(findMirrors('x.ts', source, forbidden)).toEqual([
			'x.ts:3 NoteEntryV2',
			'x.ts:5 SearchIndexStats',
			'x.ts:6 NoteEntry',
			'x.ts:11 NoteEntry',
		]);
	});

	it('honours the allowlist by file and name', () => {
		const forbidden = new Set(['FileTaskGroup']);
		const source = 'export interface FileTaskGroup {}';
		const allowlist = ['src/lib/features/example/example.types.ts -> FileTaskGroup'];
		expect(findMirrors('src/lib/features/example/example.types.ts', source, forbidden, allowlist)).toEqual([]);
		expect(findMirrors('src/lib/features/other.types.ts', source, forbidden, allowlist)).toEqual([
			'src/lib/features/other.types.ts:1 FileTaskGroup',
		]);
	});

	it('reads the generated names from the ts-rs output', () => {
		const names = generatedNames();
		expect(names).toContain('NoteEntry');
		expect(names).toContain('JsonValue');
	});

	it('no file in src/lib declares a generated type or a renamed mirror', () => {
		const forbidden = forbiddenNames();
		const hits = libFiles().flatMap((abs) =>
			findMirrors(relative(ROOT, abs), readFileSync(abs, 'utf8'), forbidden),
		);
		expect(hits).toEqual([]);
	});

	it('the contracts barrel exports every generated type', () => {
		const barrel = readFileSync(join(LIB, 'contracts/index.ts'), 'utf8');
		const missing = generatedNames().filter(
			(name) => !new RegExp(`export type \\{ ${name} \\} from`).test(barrel),
		);
		expect(missing).toEqual([]);
	});

	it('every allowlist entry still matches a declaration', () => {
		const forbidden = forbiddenNames();
		for (const entry of ALLOWLIST) {
			const [file, name] = entry.split(' -> ');
			const source = readFileSync(join(ROOT, file), 'utf8');
			const declared = [...source.matchAll(DECLARATION)].some((m) => declaredName(m) === name);
			expect(declared, entry).toBe(true);
			expect(forbidden.has(name), entry).toBe(true);
		}
	});
});
